/**
 * Which way the pill's icon points. Kept as its own tri-state type rather than a `Boolean` so a
 * true zero-change reading (`FLAT`) is a real, distinct case instead of being forced into "up" or
 * "down" -- a 0.00% move is not actually a rise or a fall.
 */
enum class ChangeDirection { UP, DOWN, FLAT }

/**
 * 💡 THOUGHT PROCESS:
 * Every change-percent readout in this app used to be plain colored text (e.g. "-2.30%"), with the
 * direction only implied by the sign character and the text color. That is easy to miss at a glance
 * on a dense screen. This pulls it into its own small pill -- a triangle plus the percentage -- so
 * direction reads as a shape, not just a color. Since the triangle already carries the sign,
 * `changeText` is expected WITHOUT a leading "+"/"-" -- callers pass the magnitude only (e.g.
 * "2.41%"), never a pre-signed string, so the direction is not stated twice.
 *
 * Icon direction and pill color are deliberately two separate inputs (`direction` vs `pillColor`/
 * `contentColor`) rather than one derived from the other. For most cards they agree (a positive move
 * gets an up triangle on a bullish-tinted pill), but VIX inverts the color semantics -- a rising VIX is
 * bearish for equities, so its pill is colored bearish even though the number itself went up. Keeping
 * the icon tied to the raw numeric sign and the color tied to whatever the caller decides is
 * "good/bad" means callers do not have to fake a sign flip just to get the right color.
 *
 * A thin wrapper around `SignalPill` (the triangle as its `leadingIcon` slot) rather than a second,
 * near-duplicate pill implementation -- sizing, padding, and the lighter pill-text treatment all
 * come from there, so the two stay visually identical by construction, not by convention.
 *
 * Icon is a solid filled triangle (`ic_triangle_up`/`ic_triangle_down`) for UP/DOWN, or a flat bar
 * (`ic_trend_flat`) for FLAT -- all separate assets from the hollow chevron `ic_arrow_up`/
 * `ic_arrow_down` used elsewhere for expand/collapse toggles. A chevron and a filled directional
 * glyph read as different affordances, so this keeps them as distinct drawables rather than reusing
 * the chevron for a second, unrelated meaning.
 */
@Composable
fun DirectionalChangePill(
    changeText: String,
    direction: ChangeDirection,
    pillColor: Color,
    contentColor: Color,
    modifier: Modifier = Modifier
) {
    val iconRes = when (direction) {
        ChangeDirection.UP -> R.drawable.ic_triangle_up
        ChangeDirection.DOWN -> R.drawable.ic_triangle_down
        ChangeDirection.FLAT -> R.drawable.ic_trend_flat
    }

    SignalPill(
        text = changeText,
        pillColor = pillColor,
        contentColor = contentColor,
        modifier = modifier,
        leadingIcon = {
            Icon(
                painter = painterResource(id = iconRes),
                contentDescription = null,
                tint = contentColor,
                modifier = Modifier.size(dimensionResource(id = R.dimen.icon_size_small))
            )
        }
    )
}

