        val pulseColors = LocalPulseColors.current
        Row {
            DirectionalChangePill(
                changeText = "2.41%",
                direction = ChangeDirection.UP,
                pillColor = pulseColors.signalBullishPill,
                contentColor = pulseColors.signalBullishText
            )
            Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_small)))
            DirectionalChangePill(
                changeText = "2.30%",
                direction = ChangeDirection.DOWN,
                pillColor = pulseColors.signalBearishPill,
                contentColor = pulseColors.signalBearishText
            )
            Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_small)))
            DirectionalChangePill(
                changeText = "0.00%",
                direction = ChangeDirection.FLAT,
                pillColor = pulseColors.signalNeutralPill,
                contentColor = pulseColors.signalNeutralText
            )
        }
    }
}

